@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@200;300;400;500;600;700;800;900&family=Amiri:wght@400;700&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  /* Colors */
  --chicken-orange: 230 126 34; /* #e67e22 */
  --chicken-gold: 241 196 15; /* #f1c40f */
  --chicken-black: 45 52 54; /* #2d3436 */
  --warm-white: 253 251 251; /* #fdfbfb */

  /* Light theme colors */
  --background: 0 0% 100%;
  --foreground: 230 100% 9%;

  --card: 0 0% 100%;
  --card-foreground: 230 100% 9%;

  --popover: 0 0% 100%;
  --popover-foreground: 230 100% 9%;

  --primary: var(--chicken-orange);
  --primary-foreground: 0 0% 98%;

  --secondary: 0 0% 96%;
  --secondary-foreground: 0 0% 9%;

  --muted: 0 0% 96%;
  --muted-foreground: 0 0% 45%;

  --accent: var(--chicken-gold);
  --accent-foreground: 0 0% 9%;

  --destructive: 0 84% 60%;
  --destructive-foreground: 0 0% 98%;

  --border: 0 0% 90%;
  --input: 0 0% 90%;
  --ring: var(--chicken-orange);

  --radius: 0.5rem;
}

.dark {
  --background: 230 100% 4%;
  --foreground: 0 0% 98%;

  --card: 230 100% 4%;
  --card-foreground: 0 0% 98%;

  --popover: 230 100% 4%;
  --popover-foreground: 0 0% 98%;

  --primary: var(--chicken-orange);
  --primary-foreground: 0 0% 9%;

  --secondary: 230 100% 9%;
  --secondary-foreground: 0 0% 98%;

  --muted: 230 100% 9%;
  --muted-foreground: 0 0% 63%;

  --accent: var(--chicken-gold);
  --accent-foreground: 0 0% 9%;

  --destructive: 0 62% 30%;
  --destructive-foreground: 0 0% 98%;

  --border: 230 100% 9%;
  --input: 230 100% 9%;
  --ring: var(--chicken-orange);
}

* {
  @apply border-border;
}

body {
  @apply bg-background text-foreground;
  font-family: 'Cairo', 'Arial', sans-serif;
  direction: rtl;
}

.font-amiri {
  font-family: 'Amiri', serif;
}

/* Custom styles */
.hero-bg {
  background: linear-gradient(135deg, hsl(var(--chicken-orange)) 0%, #d35400 25%, hsl(var(--chicken-gold)) 100%);
  background-size: 200% 200%;
  animation: gradientShift 8s ease-in-out infinite;
}

@keyframes gradientShift {
  0%, 100% {
    background-position: 0% 50%;
  }
  50% {
    background-position: 100% 50%;
  }
}

.menu-card {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.menu-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

.cart-item {
  border-bottom: 1px solid hsl(var(--border));
}

.cart-item:last-child {
  border-bottom: none;
}

/* Loading animation */
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.animate-spin {
  animation: spin 1s linear infinite;
}

/* Custom utilities */
.bg-chicken-orange {
  background-color: hsl(var(--chicken-orange));
}

.text-chicken-orange {
  color: hsl(var(--chicken-orange));
}

.border-chicken-orange {
  border-color: hsl(var(--chicken-orange));
}

.bg-chicken-gold {
  background-color: hsl(var(--chicken-gold));
}

.text-chicken-gold {
  color: hsl(var(--chicken-gold));
}

.bg-chicken-black {
  background-color: hsl(var(--chicken-black));
}

.text-chicken-black {
  color: hsl(var(--chicken-black));
}

.bg-warm-white {
  background-color: hsl(var(--warm-white));
}

/* Hover states */
.hover\:bg-chicken-orange:hover {
  background-color: hsl(var(--chicken-orange));
}

.hover\:text-chicken-orange:hover {
  color: hsl(var(--chicken-orange));
}

.hover\:bg-chicken-gold:hover {
  background-color: hsl(var(--chicken-gold));
}

.hover\:text-chicken-gold:hover {
  color: hsl(var(--chicken-gold));
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: #f1f1f1;
}

::-webkit-scrollbar-thumb {
  background: hsl(var(--chicken-orange));
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #d35400;
}

/* Line clamp utility */
.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.line-clamp-3 {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Animation for buttons */
.transform {
  transition: transform 0.2s ease-in-out;
}

.hover\:scale-105:hover {
  transform: scale(1.05);
}

/* Box shadow utilities */
.shadow-xl {
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04);
}

/* Custom responsive breakpoints */
@media (max-width: 768px) {
  body {
    font-size: 14px;
  }

  .hero-bg h1 {
    font-size: 2.5rem;
  }

  .menu-card {
    margin-bottom: 1rem;
  }
}

/* RTL specific adjustments */
[dir="rtl"] .space-x-reverse > :not([hidden]) ~ :not([hidden]) {
  --tw-space-x-reverse: 1;
  margin-right: calc(1rem * var(--tw-space-x-reverse));
  margin-left: calc(1rem * calc(1 - var(--tw-space-x-reverse)));
}

/* Focus states for accessibility */
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 2px solid hsl(var(--chicken-orange));
  outline-offset: 2px;
