import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { useToast } from "@/hooks/use-toast";
import { queryClient } from "@/lib/queryClient";
import { apiRequest } from "@/lib/queryClient";
import FileUpload from "@/components/ui/file-upload";
import type { MenuItemWithCategory, Category } from "@shared/schema";

export default function MenuManagement() {
  const [editingItem, setEditingItem] = useState<MenuItemWithCategory | null>(null);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [currentImageUrl, setCurrentImageUrl] = useState<string>("");
  const { toast } = useToast();

  const { data: menuItems = [], isLoading: itemsLoading } = useQuery<MenuItemWithCategory[]>({
    queryKey: ["/api/menu-items"],
  });

  const { data: categories = [] } = useQuery<Category[]>({
    queryKey: ["/api/categories"],
  });

  const createItemMutation = useMutation({
    mutationFn: async (data: any) => {
      await apiRequest("POST", "/api/admin/menu-items", data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/menu-items"] });
      toast({ title: "تم إنشاء العنصر بنجاح" });
      setIsDialogOpen(false);
    },
    onError: () => {
      toast({ title: "خطأ في إنشاء العنصر", variant: "destructive" });
    },
  });

  const updateItemMutation = useMutation({
    mutationFn: async ({ id, data }: { id: string; data: any }) => {
      await apiRequest("PUT", `/api/admin/menu-items/${id}`, data);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/menu-items"] });
      toast({ title: "تم تحديث العنصر بنجاح" });
      setEditingItem(null);
      setIsDialogOpen(false);
    },
    onError: () => {
      toast({ title: "خطأ في تحديث العنصر", variant: "destructive" });
    },
  });

  const deleteItemMutation = useMutation({
    mutationFn: async (id: string) => {
      await apiRequest("DELETE", `/api/admin/menu-items/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/menu-items"] });
      toast({ title: "تم حذف العنصر بنجاح" });
    },
    onError: () => {
      toast({ title: "خطأ في حذف العنصر", variant: "destructive" });
    },
  });

  const handleSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get("name") as string,
      nameAr: formData.get("nameAr") as string,
      description: formData.get("description") as string,
      descriptionAr: formData.get("descriptionAr") as string,
      price: formData.get("price") as string,
      categoryId: formData.get("categoryId") as string,
      imageUrl: currentImageUrl || (formData.get("imageUrl") as string),
      isAvailable: formData.get("isAvailable") === "on",
      calories: formData.get("calories") ? parseInt(formData.get("calories") as string) : null,
    };

    if (editingItem) {
      updateItemMutation.mutate({ id: editingItem.id, data });
    } else {
      createItemMutation.mutate(data);
    }
  };

  const resetDialog = () => {
    setEditingItem(null);
    setCurrentImageUrl("");
    setIsDialogOpen(false);
  };

  const handleEditItem = (item: MenuItemWithCategory) => {
    setEditingItem(item);
    setCurrentImageUrl(item.imageUrl || "");
    setIsDialogOpen(true);
  };

  const handleNewItem = () => {
    setEditingItem(null);
    setCurrentImageUrl("");
    setIsDialogOpen(true);
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4 space-x-reverse">
              <Link href="/admin">
                <Button variant="ghost" size="sm">
                  <i className="fas fa-arrow-right ml-2"></i>
                  العودة
                </Button>
              </Link>
              <h1 className="font-amiri font-bold text-3xl text-chicken-black">
                إدارة قائمة الطعام
              </h1>
            </div>

            <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
              <DialogTrigger asChild>
                <Button 
                  className="bg-chicken-orange hover:bg-orange-600 shadow-lg transform hover:scale-105 transition-all duration-200"
                  onClick={handleNewItem}
                >
                  <i className="fas fa-plus ml-2"></i>
                  إضافة عنصر جديد
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-gradient-to-br from-white to-orange-50">
                <DialogHeader>
                  <DialogTitle className="text-2xl font-bold text-chicken-black flex items-center">
                    <i className={`${editingItem ? 'fas fa-edit' : 'fas fa-plus-circle'} ml-3 text-chicken-orange`}></i>
                    {editingItem ? "تعديل العنصر" : "إضافة عنصر جديد"}
                  </DialogTitle>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-6">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="nameAr" className="text-sm font-semibold text-chicken-black">الاسم بالعربية *</Label>
                      <Input
                        id="nameAr"
                        name="nameAr"
                        defaultValue={editingItem?.nameAr || ""}
                        required
                        className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="name" className="text-sm font-semibold text-chicken-black">الاسم بالإنجليزية</Label>
                      <Input
                        id="name"
                        name="name"
                        defaultValue={editingItem?.name || ""}
                        className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm"
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="descriptionAr" className="text-sm font-semibold text-chicken-black">الوصف بالعربية</Label>
                    <Textarea
                      id="descriptionAr"
                      name="descriptionAr"
                      defaultValue={editingItem?.descriptionAr || ""}
                      rows={3}
                      className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="description" className="text-sm font-semibold text-chicken-black">الوصف بالإنجليزية</Label>
                    <Textarea
                      id="description"
                      name="description"
                      defaultValue={editingItem?.description || ""}
                      rows={3}
                      className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="price" className="text-sm font-semibold text-chicken-black">السعر (ريال) *</Label>
                      <Input
                        id="price"
                        name="price"
                        type="number"
                        step="0.01"
                        defaultValue={editingItem?.price || ""}
                        required
                        className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="categoryId" className="text-sm font-semibold text-chicken-black">الفئة *</Label>
                      <Select name="categoryId" defaultValue={editingItem?.categoryId || ""} required>
                        <SelectTrigger className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm">
                          <SelectValue placeholder="اختر الفئة" />
                        </SelectTrigger>
                        <SelectContent>
                          {categories.map((category) => (
                            <SelectItem key={category.id} value={category.id}>
                              {category.nameAr}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  <div className="bg-gradient-to-br from-orange-50 to-white p-6 rounded-xl border-2 border-orange-200 shadow-sm">
                    <FileUpload
                      onFileUploaded={(url) => setCurrentImageUrl(url)}
                      endpoint="/api/upload/menu-item-image"
                      currentImage={currentImageUrl}
                      label="صورة المنتج"
                      accept="image/*"
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="calories" className="text-sm font-semibold text-chicken-black">السعرات الحرارية</Label>
                      <Input
                        id="calories"
                        name="calories"
                        type="number"
                        defaultValue={editingItem?.calories || ""}
                        className="bg-orange-50/50 border-2 border-orange-200 focus:border-chicken-orange focus:bg-white transition-all duration-200 shadow-sm"
                      />
                    </div>
                    <div className="flex items-center space-x-2 space-x-reverse pt-8">
                      <Switch
                        id="isAvailable"
                        name="isAvailable"
                        defaultChecked={editingItem?.isAvailable ?? true}
                        className="data-[state=checked]:bg-chicken-orange"
                      />
                      <Label htmlFor="isAvailable" className="text-sm font-semibold text-chicken-black">متاح للطلب</Label>
                    </div>
                  </div>

                  <div className="flex justify-end space-x-2 space-x-reverse pt-4">
                    <Button type="button" variant="outline" onClick={resetDialog}>
                      إلغاء
                    </Button>
                    <Button
                      type="submit"
                      className="bg-chicken-orange hover:bg-orange-600"
                      disabled={createItemMutation.isPending || updateItemMutation.isPending}
                    >
                      {editingItem ? "تحديث" : "إضافة"}
                    </Button>
                  </div>
                </form>
              </DialogContent>
            </Dialog>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Menu Items Grid */}
        {itemsLoading ? (
          <div className="flex justify-center items-center py-20">
            <div className="animate-spin w-8 h-8 border-4 border-chicken-orange border-t-transparent rounded-full"></div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {menuItems.map((item) => (
              <Card key={item.id} className="overflow-hidden">
                <div className="aspect-square overflow-hidden">
                  {item.imageUrl ? (
                    <img
                      src={item.imageUrl}
                      alt={item.nameAr}
                      className="w-full h-full object-cover"
                      loading="lazy"
                      onError={(e) => {
                        console.error('Failed to load admin image:', item.imageUrl);
                        const target = e.target as HTMLImageElement;
                        target.src = 'data:image/svg+xml;base64,';
                      }}
                    />
                  ) : (
                    <div className="w-full h-full bg-gray-200 flex items-center justify-center">
                      <i className="fas fa-image text-4xl text-gray-400"></i>
                    </div>
                  )}
                </div>
                <CardContent className="p-4">
                  <div className="flex items-start justify-between mb-2">
                    <h3 className="font-bold text-lg truncate">{item.nameAr}</h3>
                    <Badge variant={item.isAvailable ? "default" : "secondary"}>
                      {item.isAvailable ? "متاح" : "غير متاح"}
                    </Badge>
                  </div>
                  <p className="text-gray-600 text-sm mb-2 line-clamp-2">
                    {item.descriptionAr}
                  </p>
                  <p className="text-chicken-orange font-bold text-xl mb-4">
                    {parseFloat(item.price).toFixed(2)} ريال
                  </p>
                  <div className="flex space-x-2 space-x-reverse">
                    <Button
                      onClick={() => handleEditItem(item)}
                      variant="outline"
                      size="sm"
                      className="flex-1"
                    >
                      <i className="fas fa-edit ml-1"></i>
                      تعديل
                    </Button>
                    <Button
                      onClick={() => deleteItemMutation.mutate(item.id)}
                      variant="destructive"
                      size="sm"
                      disabled={deleteItemMutation.isPending}
                    >
                      <i className="fas fa-trash ml-1"></i>
                      حذف
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}

        {!itemsLoading && menuItems.length === 0 && (
          <div className="text-center py-20">
            <i className="fas fa-utensils text-6xl text-gray-300 mb-4"></i>
            <h3 className="text-xl font-semibold text-gray-600 mb-2">لا توجد عناصر في القائمة</h3>
            <p className="text-gray-500">ابدأ بإضافة أول عنصر في قائمة طعامك</p>
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/admin/orders.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { queryClient } from "@/lib/queryClient";
import { apiRequest } from "@/lib/queryClient";
import type { OrderWithItems } from "@shared/schema";

export default function AdminOrders() {
  const { toast } = useToast();

  const { data: orders = [], isLoading } = useQuery<OrderWithItems[]>({
    queryKey: ["/api/orders"],
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      await apiRequest("PATCH", `/api/orders/${id}/status`, { status });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/orders"] });
      toast({ title: "تم تحديث حالة الطلب بنجاح" });
    },
    onError: () => {
      toast({ title: "خطأ في تحديث حالة الطلب", variant: "destructive" });
    },
  });

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
      case 'pending': return 'destructive';
      case 'confirmed': return 'default';
      case 'preparing': return 'secondary';
      case 'out_for_delivery': return 'outline';
      case 'delivered': return 'default';
      case 'cancelled': return 'destructive';
      default: return 'secondary';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'pending': return 'معلق';
      case 'confirmed': return 'مؤكد';
      case 'preparing': return 'قيد التحضير';
      case 'out_for_delivery': return 'في الطريق';
      case 'delivered': return 'تم التسليم';
      case 'cancelled': return 'ملغي';
      default: return status;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="flex items-center space-x-4 space-x-reverse">
            <Link href="/admin">
              <Button variant="ghost" size="sm">
                <i className="fas fa-arrow-right ml-2"></i>
                العودة
              </Button>
            </Link>
            <h1 className="font-amiri font-bold text-3xl text-chicken-black">
              إدارة الطلبات
            </h1>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex justify-center items-center py-20">
            <div className="animate-spin w-8 h-8 border-4 border-chicken-orange border-t-transparent rounded-full"></div>
          </div>
        ) : (
          <div className="space-y-6">
            {orders.map((order) => (
              <Card key={order.id}>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle className="flex items-center space-x-2 space-x-reverse">
                        <span>طلب #{order.id.slice(0, 8)}</span>
                        <Badge variant={getStatusBadgeVariant(order.status)}>
                          {getStatusText(order.status)}
                        </Badge>
                      </CardTitle>
                      <p className="text-gray-600 mt-1">
                        {new Date(order.createdAt).toLocaleString('ar-SA')}
                      </p>
                    </div>
                    <div className="text-right">
                      <p className="font-bold text-xl text-chicken-orange">
                        {parseFloat(order.totalAmount).toFixed(2)} ريال
                      </p>
                      <p className="text-sm text-gray-600">
                        {order.paymentMethod === 'cash_on_delivery' ? 'دفع عند التسليم' : 'دفع إلكتروني'}
                      </p>
                    </div>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {/* Customer Info */}
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <h4 className="font-semibold mb-2">معلومات العميل</h4>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                      <div>
                        <strong>الاسم:</strong> {order.guestName || "عميل مسجل"}
                      </div>
                      <div>
                        <strong>الهاتف:</strong> {order.guestPhone}
                      </div>
                      <div className="md:col-span-2">
                        <strong>العنوان:</strong> {order.street}, {order.area}, {order.city}
                        {order.buildingNumber && ` - مبنى ${order.buildingNumber}`}
                        {order.apartmentNumber && ` - شقة ${order.apartmentNumber}`}
                        {(order as any).latitude && (order as any).longitude && (
                          <div className="bg-blue-50 p-4 rounded-lg border-l-4 border-blue-400 mt-3">
                            <div className="flex items-center justify-between mb-3">
                              <div className="flex items-center space-x-2 space-x-reverse">
                                <i className="fas fa-map-marker-alt text-blue-600"></i>
                                <span className="font-medium text-blue-800">موقع جغرافي محدد</span>
                              </div>
                              <span className="bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full">GPS</span>
                            </div>
                            <div className="grid grid-cols-2 gap-3 text-sm text-blue-700 mb-3">
                              <div>
                                <span className="font-medium">خط العرض:</span>
                                <br />
                                <span className="font-mono">{parseFloat((order as any).latitude).toFixed(6)}</span>
                              </div>
                              <div>
                                <span className="font-medium">خط الطول:</span>
                                <br />
                                <span className="font-mono">{parseFloat((order as any).longitude).toFixed(6)}</span>
                              </div>
                            </div>
                            <div className="flex space-x-2 space-x-reverse">
                              <a
                                href={`https://www.google.com/maps?q=${(order as any).latitude},${(order as any).longitude}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center px-3 py-1.5 bg-blue-600 text-white text-sm rounded-md hover:bg-blue-700 transition-colors"
                              >
                                <i className="fas fa-external-link-alt mr-1"></i>
                                عرض على الخريطة
                              </a>
                              <a
                                href={`https://maps.google.com/maps?daddr=${(order as any).latitude},${(order as any).longitude}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="inline-flex items-center px-3 py-1.5 bg-green-600 text-white text-sm rounded-md hover:bg-green-700 transition-colors"
                              >
                                <i className="fas fa-directions mr-1"></i>
                                الاتجاهات
                              </a>
                            </div>
                          </div>
                        )}
                      </div>
                      {order.addressDetails && (
                        <div className="md:col-span-2">
                          <strong>تفاصيل إضافية:</strong> {order.addressDetails}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Order Items */}
                  <div>
                    <h4 className="font-semibold mb-3">عناصر الطلب</h4>
                    <div className="space-y-2">
                      {order.items?.map((item, index) => (
                        <div key={index} className="flex items-center justify-between py-2 border-b border-gray-100">
                          <div className="flex items-center space-x-3 space-x-reverse">
                            {item.menuItem?.imageUrl && (
                              <img
                                src={item.menuItem.imageUrl}
                                alt={item.menuItem.nameAr}
                                className="w-12 h-12 object-cover rounded-lg"
                              />
                            )}
                            <div>
                              <p className="font-medium">{item.menuItem?.nameAr}</p>
                              <p className="text-sm text-gray-600">
                                {parseFloat(item.priceAtOrder).toFixed(2)} ريال × {item.quantity}
                              </p>
                            </div>
                          </div>
                          <div className="font-semibold">
                            {(parseFloat(item.priceAtOrder) * item.quantity).toFixed(2)} ريال
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>

                  {/* Notes */}
                  {order.notes && (
                    <div className="bg-yellow-50 p-4 rounded-lg">
                      <h4 className="font-semibold mb-2">ملاحظات العميل</h4>
                      <p className="text-sm">{order.notes}</p>
                    </div>
                  )}

                  {/* Actions */}
                  <div className="flex items-center justify-between pt-4 border-t">
                    <div className="flex items-center space-x-2 space-x-reverse">
                      <span className="text-sm">تحديث الحالة:</span>
                      <Select
                        value={order.status}
                        onValueChange={(status) => updateStatusMutation.mutate({ id: order.id, status })}
                      >
                        <SelectTrigger className="w-40">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="pending">معلق</SelectItem>
                          <SelectItem value="confirmed">مؤكد</SelectItem>
                          <SelectItem value="preparing">قيد التحضير</SelectItem>
                          <SelectItem value="out_for_delivery">في الطريق</SelectItem>
                          <SelectItem value="delivered">تم التسليم</SelectItem>
                          <SelectItem value="cancelled">ملغي</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => window.print()}
                    >
                      <i className="fas fa-print ml-2"></i>
                      طباعة
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}

            {orders.length === 0 && (
              <div className="text-center py-20">
                <i className="fas fa-clipboard-list text-6xl text-gray-300 mb-4"></i>
                <h3 className="text-xl font-semibold text-gray-600 mb-2">لا توجد طلبات حتى الآن</h3>
                <p className="text-gray-500">ستظهر الطلبات هنا عند وصولها</p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

client/src/pages/admin/reservations.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import { Link } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { queryClient } from "@/lib/queryClient";
import { apiRequest } from "@/lib/queryClient";
import type { Reservation } from "@shared/schema";

export default function AdminReservations() {
  const { toast } = useToast();

  const { data: reservations = [], isLoading } = useQuery<Reservation[]>({
    queryKey: ["/api/reservations"],
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      await apiRequest("PATCH", `/api/reservations/${id}/status`, { status });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/reservations"] });
      toast({ title: "تم تحديث حالة الحجز بنجاح" });
    },
    onError: () => {
      toast({ title: "خطأ في تحديث حالة الحجز", variant: "destructive" });
    },
  });

  const getStatusBadgeVariant = (status: string) => {
    switch (status) {
      case 'pending': return 'destructive';
      case 'confirmed': return 'default';
      case 'cancelled': return 'destructive';
      default: return 'secondary';
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case 'pending': return 'معلق';
      case 'confirmed': return 'مؤكد';
      case 'cancelled': return 'ملغي';
      default: return status;
    }
  };

  const getSpecialOccasionText = (occasion: string) => {
    switch (occasion) {
      case 'birthday': return 'عيد ميلاد';
      case 'anniversary': return 'ذكرى سنوية';
      case 'business': return 'عمل';
      case 'other': return 'أخرى';
      default: return occasion || 'غير محدد';
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-6">
          <div className="flex items-center space-x-4 space-x-reverse">
            <Link href="/admin">
              <Button variant="ghost" size="sm">
                <i className="fas fa-arrow-right ml-2"></i>
                العودة
              </Button>
            </Link>
            <h1 className="font-amiri font-bold text-3xl text-chicken-black">
              إدارة الحجوزات
            </h1>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {isLoading ? (
          <div className="flex justify-center items-center py-20">
            <div className="animate-spin w-8 h-8 border-4 border-chicken-orange border-t-transparent rounded-full"></div>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {reservations.map((reservation) => (
              <Card key={reservation.id} className="overflow-hidden">
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <CardTitle className="text-lg truncate">
                      {reservation.guestName || "ضيف"}
                    </CardTitle>
                    <Badge variant={getStatusBadgeVariant(reservation.status)}>
                      {getStatusText(reservation.status)}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {/* Contact Info */}
                  <div className="space-y-2">
                    <div className="flex items-center space-x-2 space-x-reverse text-sm">
                      <i className="fas fa-phone text-chicken-orange"></i>
                      <span>{reservation.guestPhone}</span>
                    </div>
                    {reservation.guestEmail && (
                      <div className="flex items-center space-x-2 space-x-reverse text-sm">
                        <i className="fas fa-envelope text-chicken-orange"></i>
                        <span className="truncate">{reservation.guestEmail}</span>
                      </div>
                    )}
                  </div>

                  {/* Reservation Details */}
                  <div className="bg-gray-50 p-3 rounded-lg space-y-2 text-sm">
                    <div className="flex items-center justify-between">
                      <span className="font-medium">التاريخ:</span>
                      <span>{new Date(reservation.reservationDate).toLocaleDateString('ar-SA')}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="font-medium">الوقت:</span>
                      <span>{new Date(reservation.reservationDate).toLocaleTimeString('ar-SA', { 
                        hour: '2-digit', 
                        minute: '2-digit' 
                      })}</span>
                    </div>
                    <div className="flex items-center justify-between">
                      <span className="font-medium">عدد الأشخاص:</span>
                      <span>{reservation.numberOfGuests} شخص</span>
                    </div>
                    {reservation.specialOccasion && (
                      <div className="flex items-center justify-between">
                        <span className="font-medium">المناسبة:</span>
                        <span>{getSpecialOccasionText(reservation.specialOccasion)}</span>
                      </div>
                    )}
                  </div>

                  {/* Notes */}
                  {reservation.notes && (
                    <div className="bg-yellow-50 p-3 rounded-lg">
                      <h4 className="font-medium text-sm mb-1">ملاحظات:</h4>
                      <p className="text-sm text-gray-700">{reservation.notes}</p>
                    </div>
                  )}

                  {/* Actions */}
                  <div className="pt-4 border-t">
                    <div className="flex items-center justify-between mb-3">
                      <span className="text-sm font-medium">الحالة:</span>
                      <Select
                        value={reservation.status}
                        onValueChange={(status) => updateStatusMutation.mutate({ id: reservation.id, status })}
                      >
                        <SelectTrigger className="w-24">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="pending">معلق</SelectItem>
                          <SelectItem value="confirmed">مؤكد</SelectItem>
                          <SelectItem value="cancelled">ملغي</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex space-x-2 space-x-reverse">
                      <Button
                        variant="outline"
                        size="sm"
                        className="flex-1"
                        onClick={() => {
                          const phone = reservation.guestPhone;
                          const message = `مرحباً ${reservation.guestName}، نود تأكيد حجزكم في مطعم تشكن هات بتاريخ ${new Date(reservation.reservationDate).toLocaleDateString('ar-SA')}`;
                          window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`);
                        }}
                      >
                        <i className="fab fa-whatsapp text-green-600 ml-1"></i>
                        واتساب
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        className="flex-1"
                        onClick={() => {
                          const phone = reservation.guestPhone;
                          window.open(`tel:${phone}`);
                        }}
                      >
                        <i className="fas fa-phone text-blue-600 ml-1"></i>
                        اتصال
                      </Button>
                    </div>
                  </div>

                  {/* Creation Date */}
                  <div className="text-xs text-gray-500 pt-2 border-t">
                    تم الإنشاء: {new Date(reservation.createdAt).toLocaleString('ar-SA')}
                  </div>
                </CardContent>
              </Card>
            ))}

            {reservations.length === 0 && (
              <div className="col-span-full text-center py-20">
                <i className="fas fa-calendar-alt text-6xl text-gray-300 mb-4"></i>
                <h3 className="text-xl font-semibold text-gray-600 mb-2">لا توجد حجوزات حتى الآن</h3>
                <p className="text-gray-500">ستظهر الحجوزات هنا عند وصولها</p>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

client/src/components/home/contact-secti.content:
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import type { WebsiteSettings } from "@shared/schema";
import { useState } from "react";
import { useToast } from "@/hooks/use-toast";

export default function ContactSection() {
  const { data: settings } = useQuery<WebsiteSettings>({
    queryKey: ["/api/website-settings"],
  });

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    subject: "",
    message: ""
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { toast } = useToast();

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    // Simulate form submission
    setTimeout(() => {
      toast({
        title: "تم إرسال الرسالة بنجاح",
        description: "سنتواصل معك في أقرب وقت ممكن",
      });
      setFormData({
        name: "",
        email: "",
        phone: "",
        subject: "",
        message: ""
      });
      setIsSubmitting(false);
    }, 1500);
  };

  const contactInfo = [
    {
      icon: "fas fa-map-marker-alt",
      title: "العنوان",
      details: [settings?.streetAddress || 'القاهرة', settings?.area || 'الخط الرئيسي'],
      color: "text-red-500"
    },
    {
      icon: "fas fa-phone",
      title: "هاتف الطلبات",
      details: [settings?.contactPhone || '+966 50 123 4567'],
      color: "text-green-500"
    },
    {
      icon: "fas fa-envelope",
      title: "البريد الإلكتروني",
      details: [settings?.contactEmail || 'info@chickenhat.com'],
      color: "text-blue-500"
    },
    {
      icon: "fas fa-clock",
      title: "ساعات العمل",
      details: [settings?.operatingHours || 'السبت - الخميس: 10:00 ص - 12:00 م\nالجمعة: 2:00 م - 12:00 م'],
      color: "text-chicken-orange"
    }
  ];

  return (
    <section id="contact" className="py-20 bg-gradient-to-br from-chicken-black via-gray-900 to-chicken-black text-white relative overflow-hidden">
      {/* Background Pattern */}
      <div className="absolute inset-0 opacity-10">
        <div className="absolute top-20 right-20 text-chicken-orange text-8xl animate-pulse">
          <i className="fas fa-phone"></i>
        </div>
        <div className="absolute bottom-20 left-20 text-chicken-orange text-6xl animate-pulse delay-1000">
          <i className="fas fa-envelope"></i>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 relative z-10">
        {/* Section Header */}
        <div className="text-center mb-16">
          <h2 className="font-amiri font-bold text-4xl md:text-5xl mb-6">
            تواصل معنا
          </h2>
          <div className="w-24 h-1 bg-chicken-orange mx-auto mb-6"></div>
          <p className="text-gray-300 text-xl max-w-3xl mx-auto leading-relaxed font-cairo">
            نحن هنا للإجابة على جميع استفساراتكم وتلقي اقتراحاتكم. تواصلوا معنا في أي وقت
          </p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-16">
          {/* Contact Information */}
          <div className="space-y-8">
            <div>
              <h3 className="font-cairo font-bold text-2xl mb-8 flex items-center">
                <i className="fas fa-info-circle text-chicken-orange ml-3"></i>
                معلومات التواصل
              </h3>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 gap-6">
                {contactInfo.map((info, index) => (
                  <div key={index} className="bg-gray-800/50 backdrop-blur-sm p-6 rounded-xl border border-gray-700 hover:border-chicken-orange transition-all duration-300 transform hover:scale-105">
                    <div className="flex items-start">
                      <div className={`w-12 h-12 bg-gradient-to-br from-chicken-orange to-orange-600 rounded-lg flex items-center justify-center ml-4 flex-shrink-0`}>
                        <i className={`${info.icon} text-white text-lg`}></i>
                      </div>
                      <div className="flex-1">
                        <h4 className="font-cairo font-semibold text-lg mb-2 text-chicken-orange">
                          {info.title}
                        </h4>
                        {info.details.map((detail, idx) => (
                          <p key={idx} className="text-gray-300 font-cairo text-sm leading-relaxed">
                            {detail}
                          </p>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Social Media */}
            <div className="bg-gray-800/50 backdrop-blur-sm p-6 rounded-xl border border-gray-700">
              <h4 className="font-cairo font-semibold text-lg mb-4 text-chicken-orange flex items-center">
                <i className="fas fa-share-alt ml-3"></i>
                تابعنا على وسائل التواصل
              </h4>
              <div className="flex space-x-4 space-x-reverse">
                {[
                  { icon: "fab fa-instagram", color: "hover:text-pink-500", label: "Instagram", link: settings?.instagramUrl || '#' },
                  { icon: "fab fa-twitter", color: "hover:text-blue-400", label: "Twitter", link: settings?.twitterUrl || '#' },
                  { icon: "fab fa-facebook", color: "hover:text-blue-600", label: "Facebook", link: settings?.facebookUrl || '#' },
                  { icon: "fab fa-whatsapp", color: "hover:text-green-500", label: "WhatsApp", link: `https://wa.me/${(settings?.whatsappNumber || '+967738738317').replace(/[^0-9]/g, '')}` }
                ].map((social, index) => (
                  <a
                    key={index}
                    href={social.link}
                    target="_blank"
                    rel="noopener noreferrer"
                    className={`w-12 h-12 bg-gray-700 rounded-lg flex items-center justify-center text-gray-300 ${social.color} transition-all duration-300 hover:scale-110 hover:bg-gray-600`}
                    title={social.label}
                  >
                    <i className={`${social.icon} text-lg`}></i>
                  </a>
                ))}
              </div>
            </div>
          </div>

          {/* Contact Form */}
          <div className="bg-gray-800/30 backdrop-blur-sm p-8 rounded-xl border border-gray-700">
            <h3 className="font-cairo font-bold text-2xl mb-6 flex items-center text-chicken-orange">
              <i className="fas fa-paper-plane ml-3"></i>
              أرسل لنا رسالة
            </h3>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-cairo font-medium mb-2 text-gray-300">
                    الاسم الكامل *
                  </label>
                  <input
                    type="text"
                    name="name"
                    value={formData.name}
                    onChange={handleInputChange}
                    required
                    className="w-full p-3 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange transition-all duration-300"
                    placeholder="أدخل اسمك الكامل"
                  />
                </div>
                <div>
                  <label className="block text-sm font-cairo font-medium mb-2 text-gray-300">
                    رقم الهاتف *
                  </label>
                  <input
                    type="tel"
                    name="phone"
                    value={formData.phone}
                    onChange={handleInputChange}
                    required
                    className="w-full p-3 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange transition-all duration-300"
                    placeholder="966xxxxxxxxx+"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-cairo font-medium mb-2 text-gray-300">
                  البريد الإلكتروني *
                </label>
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  required
                  className="w-full p-3 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange transition-all duration-300"
                  placeholder="example@email.com"
                />
              </div>

              <div>
                <label className="block text-sm font-cairo font-medium mb-2 text-gray-300">
                  موضوع الرسالة
                </label>
                <select
                  name="subject"
                  value={formData.subject}
                  onChange={handleInputChange}
                  className="w-full p-3 bg-gray-700 border border-gray-600 rounded-lg text-white font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange transition-all duration-300"
                >
                  <option value="">اختر موضوع الرسالة</option>
                  <option value="order">استفسار عن طلب</option>
                  <option value="complaint">شكوى</option>
                  <option value="suggestion">اقتراح</option>
                  <option value="other">أخرى</option>
                </select>
              </div>

              <div>
                <label className="block text-sm font-cairo font-medium mb-2 text-gray-300">
                  الرسالة *
                </label>
                <textarea
                  name="message"
                  value={formData.message}
                  onChange={handleInputChange}
                  required
                  rows={5}
                  className="w-full p-3 bg-gray-700 border border-gray-600 rounded-lg text-white placeholder-gray-400 font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange transition-all duration-300 resize-none"
