import { useState } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";

export default function LoginPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  const [formData, setFormData] = useState({
    email: "",
    password: "",
    rememberMe: false
  });
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // Simulate login process
      await new Promise(resolve => setTimeout(resolve, 1500));

      toast({
        title: "تم تسجيل الدخول بنجاح",
        description: "مرحباً بك في تشكن هات",
      });

      setLocation("/");
    } catch (error) {
      toast({
        title: "خطأ في تسجيل الدخول",
        description: "البريد الإلكتروني أو كلمة المرور غير صحيحة",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-chicken-orange/10 via-orange-50 to-chicken-gold/10 flex items-center justify-center py-12 px-4" dir="rtl">
      <div className="w-full max-w-md">
        {/* Logo and Welcome */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-chicken-orange rounded-full mb-4">
            <i className="fas fa-drumstick-bite text-white text-3xl"></i>
          </div>
          <h1 className="font-amiri text-3xl font-bold text-chicken-black mb-2">
            تشكن هات
          </h1>
          <p className="font-cairo text-gray-600">
            مرحباً بك مرة أخرى
          </p>
        </div>

        <Card className="shadow-2xl border-0 bg-white/80 backdrop-blur-sm">
          <CardHeader className="space-y-1 text-center">
            <CardTitle className="font-cairo text-2xl font-bold text-chicken-black">
              تسجيل الدخول
            </CardTitle>
            <p className="font-cairo text-gray-600">
              سجل دخولك للوصول إلى حسابك
            </p>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* Email Field */}
              <div>
                <Label htmlFor="email" className="font-cairo text-gray-700 font-medium">
                  البريد الإلكتروني أو رقم الهاتف
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="email"
                    name="email"
                    type="text"
                    autoComplete="email"
                    required
                    value={formData.email}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-12"
                    placeholder="example@email.com أو 05xxxxxxxx"
                  />
                  <i className="fas fa-envelope absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Password Field */}
              <div>
                <Label htmlFor="password" className="font-cairo text-gray-700 font-medium">
                  كلمة المرور
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="password"
                    name="password"
                    type="password"
                    autoComplete="current-password"
                    required
                    value={formData.password}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-12"
                    placeholder="أدخل كلمة المرور"
                  />
                  <i className="fas fa-lock absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Remember Me & Forgot Password */}
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-2 space-x-reverse">
                  <Checkbox
                    id="rememberMe"
                    name="rememberMe"
                    checked={formData.rememberMe}
                    onCheckedChange={(checked) =>
                      setFormData(prev => ({ ...prev, rememberMe: !!checked }))
                    }
                  />
                  <Label htmlFor="rememberMe" className="font-cairo text-sm text-gray-600 cursor-pointer">
                    تذكرني
                  </Label>
                </div>

                <Link href="/forgot-password">
                  <Button variant="link" className="p-0 h-auto font-cairo text-chicken-orange hover:text-orange-600">
                    نسيت كلمة المرور؟
                  </Button>
                </Link>
              </div>

              {/* Submit Button */}
              <Button
                type="submit"
                disabled={isLoading}
                className="w-full h-12 bg-chicken-orange hover:bg-orange-600 text-white font-cairo text-lg font-semibold rounded-lg shadow-lg transform transition-all duration-300 hover:scale-105"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white ml-2"></div>
                    جارٍ تسجيل الدخول...
                  </div>
                ) : (
                  <div className="flex items-center justify-center">
                    <i className="fas fa-sign-in-alt ml-2"></i>
                    تسجيل الدخول
                  </div>
                )}
              </Button>
            </form>

            {/* Divider */}
            <div className="my-6">
              <Separator className="relative">
                <span className="bg-white px-2 text-gray-500 font-cairo text-sm absolute left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2">
                  أو
                </span>
              </Separator>
            </div>

            {/* Social Login */}
            <div className="space-y-3">
              <Button
                type="button"
                variant="outline"
                className="w-full h-12 font-cairo border-2 hover:bg-gray-50"
              >
                <i className="fab fa-google text-red-500 ml-2 text-lg"></i>
                تسجيل الدخول بواسطة Google
              </Button>

              <Button
                type="button"
                variant="outline"
                className="w-full h-12 font-cairo border-2 hover:bg-gray-50"
              >
                <i className="fab fa-apple text-gray-800 ml-2 text-lg"></i>
                تسجيل الدخول بواسطة Apple
              </Button>
            </div>

            {/* Sign Up Link */}
            <div className="mt-8 text-center">
              <p className="font-cairo text-gray-600">
                ليس لديك حساب؟{" "}
                <Link href="/register">
                  <Button variant="link" className="p-0 h-auto font-cairo text-chicken-orange hover:text-orange-600 font-semibold">
                    سجل الآن
                  </Button>
                </Link>
              </p>
            </div>

            {/* Guest Access */}
            <div className="mt-4 text-center">
              <Link href="/menu">
                <Button variant="ghost" className="font-cairo text-gray-600 hover:text-chicken-orange">
                  <i className="fas fa-user-times ml-2"></i>
                  متابعة كضيف
                </Button>
              </Link>
            </div>
          </CardContent>
        </Card>

        {/* Terms */}
        <div className="mt-6 text-center">
          <p className="font-cairo text-xs text-gray-500">
            بتسجيل الدخول، أنت توافق على{" "}
            <Link href="/terms" className="text-chicken-orange hover:underline">
              الشروط والأحكام
            </Link>
            {" "}و{" "}
            <Link href="/privacy" className="text-chicken-orange hover:underline">
              سياسة الخصوصية
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

