import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { LoadingSpinner } from "@/components/ui/loading-spinner";
import { Badge } from "@/components/ui/badge";
import ProductCard from "@/components/menu/product-card";
import ProductModal from "@/components/menu/product-modal";
import type { Category, MenuItemWithCategory } from "@shared/schema";

export default function MenuPage() {
  const [selectedCategory, setSelectedCategory] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [priceRange, setPriceRange] = useState([0, 200]);
  const [sortBy, setSortBy] = useState("name");
  const [selectedProduct, setSelectedProduct] = useState<MenuItemWithCategory | null>(null);

  const { data: categories = [], isLoading: categoriesLoading } = useQuery<Category[]>({
    queryKey: ["/api/categories"],
  });

  const { data: menuItems = [], isLoading: menuItemsLoading } = useQuery<MenuItemWithCategory[]>({
    queryKey: ["/api/menu-items"],
  });

  // Filter and sort menu items
  const filteredItems = menuItems.filter((item) => {
    const matchesCategory = selectedCategory === "all" || item.categoryId === selectedCategory;
    const matchesSearch = item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
                         item.description.toLowerCase().includes(searchQuery.toLowerCase());
    const matchesPrice = parseFloat(item.price) >= priceRange[0] && parseFloat(item.price) <= priceRange[1];
    return matchesCategory && matchesSearch && matchesPrice && item.available;
  }).sort((a, b) => {
    switch (sortBy) {
      case "price-low":
        return parseFloat(a.price) - parseFloat(b.price);
      case "price-high":
        return parseFloat(b.price) - parseFloat(a.price);
      case "popular":
        return (b.rating || 0) - (a.rating || 0);
      default:
        return a.name.localeCompare(b.name);
    }
  });

  const resetFilters = () => {
    setSelectedCategory("all");
    setSearchQuery("");
    setPriceRange([0, 200]);
    setSortBy("name");
  };

  if (categoriesLoading || menuItemsLoading) {
    return (
      <div className="min-h-screen bg-gray-50 pt-20">
        <div className="flex items-center justify-center py-20">
          <LoadingSpinner size="lg" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 pt-20" dir="rtl">
      {/* Hero Section */}
      <section className="bg-gradient-to-r from-chicken-black to-chicken-orange text-white py-16">
        <div className="max-w-7xl mx-auto px-4 text-center">
          <h1 className="font-amiri font-bold text-4xl md:text-6xl mb-6">
            قائمة الطعام
          </h1>
          <p className="font-cairo text-xl max-w-3xl mx-auto leading-relaxed">
            اكتشف مجموعتنا المميزة من أشهى الوجبات المحضرة بعناية فائقة
          </p>
        </div>
      </section>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Filters Section */}
        <div className="bg-white rounded-xl shadow-lg p-6 mb-8">
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
            {/* Search */}
            <div className="lg:col-span-1">
              <label className="block text-sm font-cairo font-medium mb-2 text-gray-700">
                البحث
              </label>
              <div className="relative">
                <Input
                  type="text"
                  placeholder="ابحث عن وجبة..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10 font-cairo"
                />
                <i className="fas fa-search absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
              </div>
            </div>

            {/* Category Filter */}
            <div className="lg:col-span-1">
              <label className="block text-sm font-cairo font-medium mb-2 text-gray-700">
                الفئة
              </label>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange"
              >
                <option value="all">جميع الفئات</option>
                {categories.map((category) => (
                  <option key={category.id} value={category.id}>
                    {category.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Price Range */}
            <div className="lg:col-span-1">
              <label className="block text-sm font-cairo font-medium mb-2 text-gray-700">
                السعر (ريال)
              </label>
              <div className="flex items-center space-x-2 space-x-reverse">
                <Input
                  type="number"
                  placeholder="من"
                  value={priceRange[0]}
                  onChange={(e) => setPriceRange([parseInt(e.target.value) || 0, priceRange[1]])}
                  className="flex-1 font-cairo"
                />
                <span className="text-gray-500">-</span>
                <Input
                  type="number"
                  placeholder="إلى"
                  value={priceRange[1]}
                  onChange={(e) => setPriceRange([priceRange[0], parseInt(e.target.value) || 200])}
                  className="flex-1 font-cairo"
                />
              </div>
            </div>

            {/* Sort */}
            <div className="lg:col-span-1">
              <label className="block text-sm font-cairo font-medium mb-2 text-gray-700">
                ترتيب حسب
              </label>
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="w-full p-3 border border-gray-300 rounded-lg font-cairo focus:border-chicken-orange focus:ring-1 focus:ring-chicken-orange"
              >
                <option value="name">الاسم (أ-ي)</option>
                <option value="price-low">السعر (أقل إلى أعلى)</option>
                <option value="price-high">السعر (أعلى إلى أقل)</option>
                <option value="popular">الأكثر شعبية</option>
              </select>
            </div>
          </div>

          {/* Filter Actions */}
          <div className="flex justify-between items-center mt-6 pt-6 border-t">
            <div className="flex items-center space-x-4 space-x-reverse">
              <Badge variant="outline" className="font-cairo">
                {filteredItems.length} وجبة متاحة
              </Badge>
              {(selectedCategory !== "all" || searchQuery || priceRange[0] > 0 || priceRange[1] < 200 || sortBy !== "name") && (
                <Button
                  variant="ghost"
                  onClick={resetFilters}
                  className="text-chicken-orange hover:text-orange-600 font-cairo"
                >
                  <i className="fas fa-undo ml-2"></i>
                  إعادة تعيين الفلاتر
                </Button>
              )}
            </div>
          </div>
        </div>

        {/* Category Quick Filters */}
        <div className="flex flex-wrap gap-3 mb-8">
          <Button
            variant={selectedCategory === "all" ? "default" : "outline"}
            onClick={() => setSelectedCategory("all")}
            className={`font-cairo rounded-full transition-all duration-300 ${
              selectedCategory === "all"
                ? "bg-chicken-orange text-white"
                : "border-chicken-orange text-chicken-orange hover:bg-chicken-orange hover:text-white"
            }`}
          >
            <i className="fas fa-utensils ml-2"></i>
            جميع الفئات
          </Button>
          {categories.map((category) => (
            <Button
              key={category.id}
              variant={selectedCategory === category.id ? "default" : "outline"}
              onClick={() => setSelectedCategory(category.id)}
              className={`font-cairo rounded-full transition-all duration-300 ${
                selectedCategory === category.id
                  ? "bg-chicken-orange text-white"
                  : "border-chicken-orange text-chicken-orange hover:bg-chicken-orange hover:text-white"
              }`}
            >
              {category.icon && <i className={`${category.icon} ml-2`}></i>}
              {category.name}
            </Button>
          ))}
        </div>

        {/* Menu Items Grid */}
        {filteredItems.length === 0 ? (
          <div className="text-center py-20">
            <div className="w-24 h-24 bg-gray-200 rounded-full flex items-center justify-center mx-auto mb-6">
              <i className="fas fa-search text-gray-400 text-3xl"></i>
            </div>
            <h3 className="font-cairo text-xl text-gray-600 mb-2">
              لم نجد أي وجبات تطابق بحثك
            </h3>
            <p className="font-cairo text-gray-500 mb-6">
              جرب تعديل معايير البحث أو تصفح جميع الوجبات
            </p>
            <Button
              onClick={resetFilters}
              className="bg-chicken-orange hover:bg-orange-600 text-white font-cairo"
            >
              عرض جميع الوجبات
            </Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
            {filteredItems.map((item) => (
              <ProductCard
                key={item.id}
                product={item}
                onProductClick={(product) => setSelectedProduct(product)}
              />
            ))}
          </div>
        )}

        {/* Load More Button */}
        {filteredItems.length > 0 && filteredItems.length >= 12 && (
          <div className="text-center mt-12">
            <Button
              variant="outline"
              className="border-chicken-orange text-chicken-orange hover:bg-chicken-orange hover:text-white font-cairo px-8 py-3"
            >
              عرض المزيد من الوجبات
            </Button>
          </div>
        )}
      </div>

      {/* Product Modal */}
      {selectedProduct && (
        <ProductModal
          product={selectedProduct}
          isOpen={!!selectedProduct}
          onClose={() => setSelectedProduct(null)}
        />
      )}
    </div>
  );
}

