import { useState } from "react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";

export default function RegisterPage() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();

  const [formData, setFormData] = useState({
    fullName: "",
    email: "",
    phone: "",
    password: "",
    confirmPassword: "",
    agreeToTerms: false
  });
  const [isLoading, setIsLoading] = useState(false);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value, type, checked } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const validateForm = () => {
    if (!formData.fullName.trim()) {
      toast({
        title: "خطأ في البيانات",
        description: "يرجى إدخال الاسم الكامل",
        variant: "destructive"
      });
      return false;
    }

    if (!formData.email.includes("@")) {
      toast({
        title: "خطأ في البيانات",
        description: "يرجى إدخال بريد إلكتروني صحيح",
        variant: "destructive"
      });
      return false;
    }

    if (formData.password.length < 6) {
      toast({
        title: "خطأ في البيانات",
        description: "كلمة المرور يجب أن تكون 6 أحرف على الأقل",
        variant: "destructive"
      });
      return false;
    }

    if (formData.password !== formData.confirmPassword) {
      toast({
        title: "خطأ في البيانات",
        description: "كلمتا المرور غير متطابقتان",
        variant: "destructive"
      });
      return false;
    }

    if (!formData.agreeToTerms) {
      toast({
        title: "خطأ في البيانات",
        description: "يجب الموافقة على الشروط والأحكام",
        variant: "destructive"
      });
      return false;
    }

    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) return;

    setIsLoading(true);

    try {
      // Simulate registration process
      await new Promise(resolve => setTimeout(resolve, 2000));

      toast({
        title: "تم إنشاء الحساب بنجاح",
        description: "مرحباً بك في تشكن هات",
      });

      setLocation("/");
    } catch (error) {
      toast({
        title: "خطأ في إنشاء الحساب",
        description: "حدث خطأ، يرجى المحاولة مرة أخرى",
        variant: "destructive"
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-chicken-orange/10 via-orange-50 to-chicken-gold/10 flex items-center justify-center py-12 px-4" dir="rtl">
      <div className="w-full max-w-md">
        {/* Logo and Welcome */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-chicken-orange rounded-full mb-4">
            <i className="fas fa-drumstick-bite text-white text-3xl"></i>
          </div>
          <h1 className="font-amiri text-3xl font-bold text-chicken-black mb-2">
            تشكن هات
          </h1>
          <p className="font-cairo text-gray-600">
            انضم إلى عائلة تشكن هات
          </p>
        </div>

        <Card className="shadow-2xl border-0 bg-white/80 backdrop-blur-sm">
          <CardHeader className="space-y-1 text-center">
            <CardTitle className="font-cairo text-2xl font-bold text-chicken-black">
              إنشاء حساب جديد
            </CardTitle>
            <p className="font-cairo text-gray-600">
              أنشئ حسابك للاستمتاع بمزايا إضافية
            </p>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-5">
              {/* Full Name */}
              <div>
                <Label htmlFor="fullName" className="font-cairo text-gray-700 font-medium">
                  الاسم الكامل *
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="fullName"
                    name="fullName"
                    type="text"
                    required
                    value={formData.fullName}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-11"
                    placeholder="أدخل اسمك الكامل"
                  />
                  <i className="fas fa-user absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Email */}
              <div>
                <Label htmlFor="email" className="font-cairo text-gray-700 font-medium">
                  البريد الإلكتروني *
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="email"
                    name="email"
                    type="email"
                    required
                    value={formData.email}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-11"
                    placeholder="example@email.com"
                  />
                  <i className="fas fa-envelope absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Phone */}
              <div>
                <Label htmlFor="phone" className="font-cairo text-gray-700 font-medium">
                  رقم الهاتف *
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="phone"
                    name="phone"
                    type="tel"
                    required
                    value={formData.phone}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-11"
                    placeholder="05xxxxxxxx"
                  />
                  <i className="fas fa-phone absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Password */}
              <div>
                <Label htmlFor="password" className="font-cairo text-gray-700 font-medium">
                  كلمة المرور *
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="password"
                    name="password"
                    type="password"
                    required
                    value={formData.password}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-11"
                    placeholder="أدخل كلمة المرور (6 أحرف على الأقل)"
                  />
                  <i className="fas fa-lock absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Confirm Password */}
              <div>
                <Label htmlFor="confirmPassword" className="font-cairo text-gray-700 font-medium">
                  تأكيد كلمة المرور *
                </Label>
                <div className="relative mt-1">
                  <Input
                    id="confirmPassword"
                    name="confirmPassword"
                    type="password"
                    required
                    value={formData.confirmPassword}
                    onChange={handleInputChange}
                    className="font-cairo pl-10 h-11"
                    placeholder="أعد إدخال كلمة المرور"
                  />
                  <i className="fas fa-lock absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400"></i>
                </div>
              </div>

              {/* Terms Agreement */}
              <div className="flex items-start space-x-3 space-x-reverse">
                <Checkbox
                  id="agreeToTerms"
                  name="agreeToTerms"
                  checked={formData.agreeToTerms}
                  onCheckedChange={(checked) => 
                    setFormData(prev => ({ ...prev, agreeToTerms: !!checked }))
                  }
                  className="mt-1"
                />
                <Label htmlFor="agreeToTerms" className="font-cairo text-sm text-gray-600 cursor-pointer leading-relaxed">
                  أوافق على{" "}
                  <Link href="/terms" className="text-chicken-orange hover:underline">
                    الشروط والأحكام
                  </Link>
                  {" "}و{" "}
                  <Link href="/privacy" className="text-chicken-orange hover:underline">
                    سياسة الخصوصية
                  </Link>
                </Label>
              </div>

              {/* Submit Button */}
              <Button
                type="submit"
                disabled={isLoading}
                className="w-full h-12 bg-chicken-orange hover:bg-orange-600 text-white font-cairo text-lg font-semibold rounded-lg shadow-lg transform transition-all duration-300 hover:scale-105"
              >
                {isLoading ? (
                  <div className="flex items-center justify-center">
                    <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white ml-2"></div>
                    جارٍ إنشاء الحساب...
                  </div>
                ) : (
                  <div className="flex items-center justify-center">
                    <i className="fas fa-user-plus ml-2"></i>
                    إنشاء حساب
                  </div>
                )}
              </Button>
            </form>

            {/* Divider */}
            <div className="my-6">
              <Separator className="relative">
                <span className="bg-white px-2 text-gray-500 font-cairo text-sm absolute left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2">
                  أو
                </span>
              </Separator>
            </div>

            {/* Social Registration */}
            <div className="space-y-3">
              <Button
                type="button"
                variant="outline"
                className="w-full h-11 font-cairo border-2 hover:bg-gray-50"
              >
                <i className="fab fa-google text-red-500 ml-2 text-lg"></i>
                التسجيل بواسطة Google
              </Button>

              <Button
                type="button"
                variant="outline"
                className="w-full h-11 font-cairo border-2 hover:bg-gray-50"
              >
                <i className="fab fa-apple text-gray-800 ml-2 text-lg"></i>
                التسجيل بواسطة Apple
              </Button>
            </div>

            {/* Login Link */}
            <div className="mt-6 text-center">
              <p className="font-cairo text-gray-600">
                لديك حساب بالفعل؟{" "}
                <Link href="/login">
                  <Button variant="link" className="p-0 h-auto font-cairo text-chicken-orange hover:text-orange-600 font-semibold">
                    سجل دخولك
                  </Button>
                </Link>
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

client/src/components/cart/cart-item.tsx.content:
import { Button } from "@/components/ui/button";
import { useCart } from "@/lib/cart";
import type { CartItem } from "@/lib/cart";

interface CartItemProps {
  item: CartItem;
}

export default function CartItemComponent({ item }: CartItemProps) {
  const { updateQuantity, removeItem } = useCart();

  const handleQuantityChange = (newQuantity: number) => {
    if (newQuantity <= 0) {
      removeItem(item.id);
    } else {
      updateQuantity(item.id, newQuantity);
    }
  };

  return (
    <div className="flex items-center space-x-4 space-x-reverse py-4 border-b border-gray-200 last:border-b-0">
      {/* صورة المنتج */}
      <div className="flex-shrink-0">
        <img
          src={item.image || "/placeholder-food.jpg"}
          alt={item.name}
          className="w-16 h-16 object-cover rounded-lg"
        />
      </div>

      {/* تفاصيل المنتج */}
      <div className="flex-1 min-w-0">
        <h4 className="text-sm font-semibold text-chicken-black font-cairo truncate">
          {item.name}
        </h4>
        <p className="text-xs text-gray-500 font-cairo">
          {item.category}
        </p>
        <p className="text-sm font-bold text-chicken-orange font-amiri">
          {item.price.toFixed(2)} ريال
        </p>
      </div>

      {/* أدوات التحكم في الكمية */}
      <div className="flex items-center space-x-2 space-x-reverse">
        <Button
          variant="outline"
          size="sm"
          className="h-8 w-8 p-0"
          onClick={() => handleQuantityChange(item.quantity - 1)}
        >
          <i className="fas fa-minus text-xs"></i>
        </Button>

        <span className="w-8 text-center text-sm font-semibold">
          {item.quantity}
        </span>

        <Button
          variant="outline" 
          size="sm"
          className="h-8 w-8 p-0"
          onClick={() => handleQuantityChange(item.quantity + 1)}
        >
          <i className="fas fa-plus text-xs"></i>
        </Button>
      </div>

      {/* السعر الإجمالي وزر الحذف */}
      <div className="flex flex-col items-end space-y-2">
        <span className="text-sm font-bold text-chicken-black font-amiri">
          {(item.price * item.quantity).toFixed(2)} ريال
        </span>

        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0 text-red-500 hover:text-red-700 hover:bg-red-50"
          onClick={() => removeItem(item.id)}
        >
          <i className="fas fa-trash text-xs"></i>
        </Button>
      </div>
    </div>
  );
}

client/src/components/menu/menu-category.content:
import { useState } from "react";
import { Button } from "@/components/ui/button";
import ProductCard from "./product-card";
import type { MenuItemWithCategory } from "@shared/schema";

interface MenuCategoryProps {
  categoryName: string;
  items: MenuItemWithCategory[];
  onProductClick?: (item: MenuItemWithCategory) => void;
}

export default function MenuCategory({ categoryName, items, onProductClick }: MenuCategoryProps) {
  const [showAll, setShowAll] = useState(false);
  const displayItems = showAll ? items : items.slice(0, 6);

  if (items.length === 0) {
    return null;
  }

  return (
    <div className="mb-12">
      {/* عنوان الفئة */}
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center space-x-4 space-x-reverse">
          <div className="w-1 h-8 bg-chicken-orange rounded-full"></div>
          <h2 className="font-amiri font-bold text-3xl text-chicken-black">
            {categoryName}
          </h2>
          <span className="bg-chicken-gold text-chicken-black px-3 py-1 rounded-full text-sm font-bold font-cairo">
            {items.length} منتج
          </span>
        </div>

        {items.length > 6 && (
          <Button
            variant="outline"
            onClick={() => setShowAll(!showAll)}
            className="border-chicken-orange text-chicken-orange hover:bg-chicken-orange hover:text-white font-cairo"
          >
            {showAll ? (
              <>
                <i className="fas fa-chevron-up ml-2"></i>
                عرض أقل
              </>
            ) : (
              <>
                <i className="fas fa-chevron-down ml-2"></i>
                عرض المزيد ({items.length - 6})
              </>
            )}
          </Button>
        )}
      </div>

      {/* شبكة المنتجات */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {displayItems.map((item) => (
          <ProductCard
            key={item.id}
            item={item}
            onImageClick={onProductClick}
          />
        ))}
      </div>

      {/* زر عرض المزيد للهواتف */}
      {items.length > 6 && !showAll && (
        <div className="text-center mt-6 md:hidden">
          <Button
            onClick={() => setShowAll(true)}
            className="bg-chicken-orange hover:bg-orange-600 text-white font-cairo px-8 py-3"
          >
            <i className="fas fa-chevron-down ml-2"></i>
            عرض جميع منتجات {categoryName} ({items.length - 6} المزيد)
          </Button>
        </div>
      )}
    </div>
  );
}

