import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { useCart } from "@/lib/cart";
import { useToast } from "@/hooks/use-toast";
import type { MenuItemWithCategory } from "@shared/schema";

interface ProductCardProps {
  item: MenuItemWithCategory;
  onImageClick?: (item: MenuItemWithCategory) => void;
}

export default function ProductCard({ item, onImageClick }: ProductCardProps) {
  const [isLoading, setIsLoading] = useState(false);
  const { addItem } = useCart();
  const { toast } = useToast();

  const handleAddToCart = async () => {
    setIsLoading(true);
    try {
      addItem({
        id: item.id,
        name: item.name,
        price: parseFloat(item.price),
        image: item.image || "/placeholder-food.jpg",
        category: item.category?.name || "غير مصنف"
      });

      toast({
        title: "تم الإضافة بنجاح!",
        description: `تم إضافة ${item.name} إلى سلة المشتريات`,
        variant: "default",
      });
    } catch (error) {
      toast({
        title: "خطأ",
        description: "فشل في إضافة المنتج إلى السلة",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Card className="group h-full overflow-hidden transition-all duration-300 hover:shadow-lg hover:scale-105 bg-white border border-gray-200">
      <div className="relative aspect-[4/3] overflow-hidden">
        <img
          src={item.image || "/placeholder-food.jpg"}
          alt={item.name}
          className="w-full h-full object-cover transition-transform duration-300 group-hover:scale-110 cursor-pointer"
          onClick={() => onImageClick?.(item)}
          loading="lazy"
        />
        {item.category && (
          <Badge 
            className="absolute top-2 right-2 bg-chicken-orange text-white font-cairo"
            variant="secondary"
          >
            {item.category.name}
          </Badge>
        )}
        {!item.available && (
          <div className="absolute inset-0 bg-black/50 flex items-center justify-center">
            <Badge variant="destructive" className="font-cairo">
              غير متاح حالياً
            </Badge>
          </div>
        )}
      </div>

      <CardContent className="p-4 flex flex-col h-full">
        <div className="flex-1">
          <h3 className="font-amiri font-bold text-lg text-chicken-black mb-2 line-clamp-1">
            {item.name}
          </h3>

          <p className="text-gray-600 text-sm mb-3 line-clamp-2 font-cairo leading-relaxed">
            {item.description}
          </p>

          {item.calories && (
            <p className="text-xs text-gray-500 mb-2 font-cairo">
              <i className="fas fa-fire text-chicken-orange ml-1"></i>
              {item.calories} سعرة حرارية
            </p>
          )}
        </div>

        <div className="flex items-center justify-between mt-auto pt-3 border-t border-gray-100">
          <div className="flex flex-col">
            <span className="text-2xl font-bold text-chicken-orange font-amiri">
              {parseFloat(item.price).toFixed(2)} ريال
            </span>
          </div>

          <Button
            onClick={handleAddToCart}
            disabled={!item.available || isLoading}
            className="bg-chicken-orange hover:bg-orange-600 text-white font-cairo px-6 py-2 rounded-lg transition-colors disabled:opacity-50"
          >
            {isLoading ? (
              <div className="flex items-center space-x-2 space-x-reverse">
                <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                <span>جارٍ الإضافة...</span>
              </div>
            ) : (
              <>
                <i className="fas fa-plus ml-2"></i>
                أضف للسلة
              </>
            )}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

