import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useCart } from "@/lib/cart";
import { useToast } from "@/hooks/use-toast";
import type { MenuItemWithCategory } from "@shared/schema";

interface ProductModalProps {
  item: MenuItemWithCategory | null;
  isOpen: boolean;
  onClose: () => void;
}

export default function ProductModal({ item, isOpen, onClose }: ProductModalProps) {
  const [quantity, setQuantity] = useState(1);
  const [isLoading, setIsLoading] = useState(false);
  const { addItem } = useCart();
  const { toast } = useToast();

  if (!item) return null;

  const handleAddToCart = async () => {
    setIsLoading(true);
    try {
      for (let i = 0; i < quantity; i++) {
        addItem({
          id: item.id,
          name: item.name,
          price: parseFloat(item.price),
          image: item.image || "/placeholder-food.jpg",
          category: item.category?.name || "غير مصنف"
        });
      }

      toast({
        title: "تم الإضافة بنجاح!",
        description: `تم إضافة ${quantity} من ${item.name} إلى السلة`,
        variant: "default",
      });

      onClose();
      setQuantity(1);
    } catch (error) {
      toast({
        title: "خطأ",
        description: "فشل في إضافة المنتج إلى السلة",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="font-amiri text-2xl text-chicken-black text-right">
            {item.name}
          </DialogTitle>
        </DialogHeader>

        <div className="grid md:grid-cols-2 gap-6">
          {/* صورة المنتج */}
          <div className="relative aspect-square overflow-hidden rounded-lg">
            <img
              src={item.image || "/placeholder-food.jpg"}
              alt={item.name}
              className="w-full h-full object-cover"
            />
            {item.category && (
              <Badge 
                className="absolute top-4 right-4 bg-chicken-orange text-white font-cairo"
              >
                {item.category.name}
              </Badge>
            )}
          </div>

          {/* تفاصيل المنتج */}
          <div className="space-y-4">
            <div>
              <h3 className="font-amiri font-bold text-xl text-chicken-black mb-2">
                الوصف
              </h3>
              <p className="text-gray-600 leading-relaxed font-cairo">
                {item.description}
              </p>
            </div>

            {/* المعلومات الغذائية */}
            {item.calories && (
              <div className="bg-gray-50 p-4 rounded-lg">
                <h4 className="font-cairo font-semibold text-chicken-black mb-2">
                  المعلومات الغذائية
                </h4>
                <div className="flex items-center space-x-2 space-x-reverse">
                  <i className="fas fa-fire text-chicken-orange"></i>
                  <span className="font-cairo text-gray-600">
                    {item.calories} سعرة حرارية
                  </span>
                </div>
              </div>
            )}

            {/* السعر */}
            <div className="border-t pt-4">
              <div className="flex items-center justify-between mb-4">
                <span className="font-amiri text-2xl font-bold text-chicken-orange">
                  {parseFloat(item.price).toFixed(2)} ريال
                </span>

                {!item.available && (
                  <Badge variant="destructive" className="font-cairo">
                    غير متاح حالياً
                  </Badge>
                )}
              </div>

              {/* أدوات التحكم في الكمية */}
              {item.available && (
                <div className="space-y-4">
                  <div className="flex items-center space-x-4 space-x-reverse">
                    <span className="font-cairo font-medium">الكمية:</span>
                    <div className="flex items-center space-x-2 space-x-reverse">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setQuantity(Math.max(1, quantity - 1))}
                        className="h-10 w-10 p-0"
                      >
                        <i className="fas fa-minus"></i>
                      </Button>

                      <span className="w-12 text-center font-bold text-lg">
                        {quantity}
                      </span>

                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setQuantity(quantity + 1)}
                        className="h-10 w-10 p-0"
                      >
                        <i className="fas fa-plus"></i>
                      </Button>
                    </div>
                  </div>

                  {/* زر الإضافة للسلة */}
                  <Button
                    onClick={handleAddToCart}
                    disabled={isLoading}
                    className="w-full bg-chicken-orange hover:bg-orange-600 text-white font-cairo py-3 text-lg"
                  >
                    {isLoading ? (
                      <div className="flex items-center space-x-2 space-x-reverse">
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                        <span>جارٍ الإضافة...</span>
                      </div>
                    ) : (
                      <>
                        <i className="fas fa-shopping-cart ml-2"></i>
                        أضف {quantity} إلى السلة ({(parseFloat(item.price) * quantity).toFixed(2)} ريال)
                      </>
                    )}
                  </Button>
                </div>
              )}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

